// Loop over input items and add a new field called 'myNewField' to the JSON of each one
for (const item of $input.all()) {
  item.json.myNewField = 1;
}

return $input.all();

// Group items by code_article
const grouped = {};

for (const item of $input.all()) {
  const code = item.json.code_article; 

  if (!grouped[code]) {
    grouped[code] = [];
  }
  grouped[code].push(item.json);
}

// Convert to array of groups if needed
const result = Object.keys(grouped).map(code => ({
  code_article: code,
  items: grouped[code],
  count: grouped[code].length
}));

return result;

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
article = {}
for (const item of $input.all()) {
  code = item.json.code_article
  if (!article["marque"]) {
    article["marque"] = [];
  }
  article["marque"].push(item.json.marque);
}

return article;

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "code_fournisseur": {
      "type": "string",
      "description": "Code unique du fournisseur sélectionné"
    },
    "code_article": {
      "type": "string",
      "description": "Code de l'article analysé"
    },
    "prix": {
      "type": "number",
      "description": "Prix unitaire HT en MAD"
    },
    "marque": {
      "type": "string",
      "description": "Marque proposée par le fournisseur sélectionné"
    },
    "statut": {
      "type": "string",
      "enum": ["Éligible", "Alternative", "Hors budget", "Défaut", "Secours"],
      "description": "Statut de la sélection"
    },
    "marque_autorisee": {
      "type": "boolean",
      "description": "True si la marque est dans la liste des marques autorisées"
    },
    "dans_le_budget": {
      "type": "boolean",
      "description": "True si le prix est inférieur ou égal au tarif référence"
    },
    "alerte": {
      "type": ["string", "null"],
      "enum": [null, "Marque souhaitée non trouvée", "Hors budget", "Marque attribuée par défaut", "Aucune offre dans le budget - Solution de secours"],
      "description": "Message d'alerte si applicable, sinon null"
    }
  },
  "required": ["code_fournisseur", "code_article", "prix", "marque", "statut", "marque_autorisee", "dans_le_budget", "alerte"]
}
